    import json

    from app.core.rbac import PERMISSIONS, SYSTEM_ROLES
    from app.outreach.crypto import encrypt
    conn = op.get_bind()
    for code, (zh, en) in PERMISSIONS.items():
        conn.execute(sa.text("INSERT INTO permissions(code,name_zh,name_en) VALUES (:c,:z,:e) ON CONFLICT DO NOTHING"),
                     {"c": code, "z": zh, "e": en})
    for role, (_, codes) in SYSTEM_ROLES.items():
        for c in codes:
            conn.execute(sa.text("INSERT INTO role_permissions(role_id, permission_code) SELECT id, :c FROM roles "
                                 "WHERE code=:r AND is_system ON CONFLICT DO NOTHING"), {"c": c, "r": role})
    # 解约清除时允许删除该租户的审计日志（仅当事务内 SET LOCAL tl.tenant_purge = 'on'）；其余情况仍只追加
    op.execute("""
    CREATE OR REPLACE FUNCTION audit_logs_immutable() RETURNS trigger AS $$
    BEGIN
      IF TG_OP = 'DELETE' AND current_setting('tl.tenant_purge', true) = 'on' THEN RETURN OLD; END IF;
      RAISE EXCEPTION 'audit_logs is append-only';
    END; $$ LANGUAGE plpgsql;
    """)
    # 字段级加密：存量明文银行信息 / WhatsApp 加密
    for tbl in ("tenant_compliance", "proforma_invoices"):
        for rid, val in conn.execute(sa.text(f"SELECT id, bank_info FROM {tbl} WHERE bank_info IS NOT NULL AND NOT (bank_info ? '_enc')")):
            conn.execute(sa.text(f"UPDATE {tbl} SET bank_info = CAST(:v AS jsonb) WHERE id = :i"),
                         {"v": json.dumps({"_enc": encrypt(json.dumps(val, ensure_ascii=False))}), "i": rid})
    for rid, val in conn.execute(sa.text("SELECT id, whatsapp FROM contacts WHERE whatsapp IS NOT NULL AND whatsapp NOT LIKE 'enc:%'")):
        conn.execute(sa.text("UPDATE contacts SET whatsapp = :v WHERE id = :i"), {"v": "enc:" + encrypt(val), "i": rid})


